const raw = items[0].json;
const body = raw.body || raw;

const appt = body.appointment || {};
const leadName = appt.lead_name || body.nombre || body.name || '';
const email = (appt.lead_email || body.email || '').toString().trim();
const phone = (appt.lead_phone || body.telefono || body.phone || '').toString().trim();
const startAt = appt.start_at || body.fecha_hora || body.datetime || '';
const endAt = appt.end_at || '';
const tz = appt.timezone || body.timezone || 'Europe/Madrid';
const reason = appt.reason || body.motivo || body.reason || 'Consulta inicial';
const durationMin = appt.duration_minutes || body.duration_minutes || 30;
const apptId = appt.id || '';
const icsUid = appt.ics_uid || '';

const errors = [];
if (!leadName) errors.push('lead_name');
if (!email && !phone) errors.push('lead_email o lead_phone');
if (!startAt) errors.push('start_at');

let isoStart = '';
let isoEnd = '';
let fechaFormateada = '';
try {
  const dStart = new Date(startAt);
  if (isNaN(dStart.getTime())) {
    errors.push('start_at_invalid');
  } else {
    isoStart = dStart.toISOString();
    const dEnd = endAt ? new Date(endAt) : new Date(dStart.getTime() + (Number(durationMin) || 30) * 60000);
    isoEnd = isNaN(dEnd.getTime()) ? new Date(dStart.getTime() + 30 * 60000).toISOString() : dEnd.toISOString();
    fechaFormateada = new Intl.DateTimeFormat('es-ES', {
      weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
      hour: '2-digit', minute: '2-digit', timeZone: tz, hour12: false
    }).format(dStart);
  }
} catch (e) { errors.push('start_at_invalid'); }

if (errors.length > 0) {
  return [{ json: { error: true, mensaje: 'Faltan campos o son inválidos: ' + errors.join(', '), campos_recibidos: Object.keys(body) } }];
}

const site = body.site || {};
return [{
  json: {
    error: false,
    appointment_id: apptId,
    ics_uid: icsUid,
    nombre: leadName,
    email: email,
    telefono: phone,
    motivo: reason,
    empresa: body.empresa || '',
    fecha_hora: startAt,
    fecha_iso: isoStart,
    fecha_fin_iso: isoEnd,
    fecha_formateada: fechaFormateada,
    timezone: tz,
    duration_min: Number(durationMin) || 30,
    site_name: site.name || 'Consultoría en Marketing',
    site_url: site.url || 'https://consultoriaenmarketing.com',
    admin_email: site.admin_email || 'admin@consultoriaenmarketing.com',
    crm_base_url: (body.crm && body.crm.base_url) || 'https://crm.cl1.nl'
  }
}];

const norm = $('Normalizar Payload').first().json;
const resp = items[0].json || {};
let personId = '';
try {
  if (resp.data && resp.data.createPerson && resp.data.createPerson.id) personId = resp.data.createPerson.id;
  else if (resp.id) personId = resp.id;
} catch (e) {}
return [{
  json: {
    ...norm,
    crm_person_id: personId,
    crm_response_ok: !!personId
  }
}];

